#!/usr/bin/env python3

import os
from typing import Iterator

URL_BASE = "https://github.com/TheAlgorithms/Python/blob/master"


def good_filepaths(top_dir: str = ".") -> Iterator[str]:
    for dirpath, dirnames, filenames in os.walk(top_dir):
        dirnames[:] = [d for d in dirnames if d != "scripts" and d[0] not in "._"]
        for filename in filenames:
            if filename == "__init__.py":
                continue
            if os.path.splitext(filename)[1] in (".py", ".ipynb"):
                yield os.path.join(dirpath, filename).lstrip("./")


def md_prefix(i):
    return f"{i * '  '}*" if i else "##"


def print_path(old_path: str, new_path: str) -> str:
    old_parts = old_path.split(os.sep)
    for i, new_part in enumerate(new_path.split(os.sep)):
        if i + 1 > len(old_parts) or old_parts[i] != new_part:
            if new_part:
                print(f"{md_prefix(i-1)} {new_part.replace('_', ' ').title()}")
    return new_path


def print_directory_md(top_dir: str = ".") -> None:
    old_path = ""
    for filepath in sorted(good_filepaths()):
        filepath, filename = os.path.split(filepath)
        if filepath != old_path:
            old_path = print_path(old_path, filepath)
        indent = (filepath.count(os.sep) + 1) if filepath else 0
        url = "/".join((URL_BASE, filepath.split(os.sep)[1], filename)).replace(
            " ", "%20"
        )
        filename = os.path.splitext(filename.replace("_", " "))[0]
        print(f"{md_prefix(indent)} [{filename}]({url})")


if __name__ == "__main__":
    print_directory_md(".")

Provider=SQLNCLI10;Server=myServerAddress;Database=myDataBase;Uid=myUsername;
Pwd=myPassword;

db_url      = jdbc:microsoft:sqlserver://HOST:1433;DatabaseName=DATABASE
db_driver   = com.microsoft.jdbc.sqlserver.SQLServerDriver
db_username = USERNAME
db_password = PASSWORD

SQLServerDataSource dataSource = new SQLServerDataSource();
dataSource.setURL(
    "jdbc:sqlserver://localhost;instance=SQLEXPRESS;" +
    "databaseName=high_performance_java_persistence;"
);
dataSource.setUser("sa");
dataSource.setPassword("adm1n");

