    my $file = $ARGS{TARG_DIR} . shift;
    my $hash = shift;
    my $proc = shift;
    open my $vars, '<', $file or die die "Cannot open $file: $!
";

    while (<$vars>) {
   # All symbols have a Perl_ prefix because that's what embed.h sticks
   # in front of them.  The A?I?S?C? is strictly speaking wrong.
   next unless / PERLVAR(A?I?S?C?)\(([IGT]),\s*(\w+)/;

   my $var = "PL_$3";
   my $symbol = $proc ? &$proc($1,$2,$3) : $var;
   ++$hash->{$symbol} unless exists $skip{$var};
    }
}

if ($ARGS{PLATFORM} ne 'os2') {
    ++$skip{$_} foreach qw(
           PL_cryptseen
           PL_opsave
           Perl_GetVars
           Perl_dump_fds
           Perl_my_bcopy
           Perl_my_bzero
           Perl_my_chsize
           Perl_my_htonl
           Perl_my_memcmp
           Perl_my_memset
           Perl_my_ntohl
           Perl_my_swap
          );
    if ($ARGS{PLATFORM} eq 'vms') {
   ++$skip{PL_statusvalue_posix};
        # This is a wrapper if we have symlink, not a replacement
        # if we don't.
        ++$skip{Perl_my_symlink} unless $Config{d_symlink};
    } else {
   ++$skip{PL_statusvalue_vms};
   ++$skip{PL_perllib_sep};
   if ($ARGS{PLATFORM} ne 'aix') {
       ++$skip{$_} foreach qw(
            PL_DBcv
            PL_generation
            PL_lastgotoprobe
            PL_modcount
            main
             );
   }
    }
}

my $fold;
my %ARGS;
my %define;

BEGIN {
    BEGIN { unshift @INC, "lib" }
    use Config;
    use strict;

    %ARGS = (CCTYPE => 'MSVC', TARG_DIR => '');

    sub process_cc_flags {
   foreach (map {split /\s+/, $_} @_) {
       $define{$1} = $2 // 1 if /^-D(\w+)(?:=(.+))?/;
   }
    }

    while (@ARGV) {
   my $flag = shift;
   if ($flag =~ /^(?:CC_FLAGS=)?(-D\w.*)/) {
       process_cc_flags($1);
   } elsif ($flag =~ /^(CCTYPEFILETYPEPLATFORMTARG_DIR)=(.+)$/) {
       $ARGS{$1} = $2;
   } elsif ($flag eq '--sort-fold') {
       ++$fold;
   }
    }
    my @PLATFORM = qw(aix win32 os2 netware vms test);
    my %PLATFORM;
    @PLATFORM{@PLATFORM} = ();

    die "PLATFORM undefined, must be one of: @PLATFORM
"
   unless defined $ARGS{PLATFORM};
    die "PLATFORM must be one of: @PLATFORM
"
   unless exists $PLATFORM{$ARGS{PLATFORM}};
}
use constant PLATFORM => $ARGS{PLATFORM};

require "./$ARGS{TARG_DIR}regen/embed_lib.pl";


# perl.h logic duplication ends

print STDERR "Defines: (" . join(' ', sort keys %define) . ")
"
     unless $ARGS{PLATFORM} eq 'test';

my $sym_ord = 0;
my %ordinal;

if ($ARGS{PLATFORM} eq 'os2') {
    if (open my $fh, '<', 'perl5.def') {
      while (<$fh>) {
   last if /^\s*EXPORTS /;
      }
      while (<$fh>) {
   $ordinal{$1} = $2 if /^\s*"(\w+)"\s*(?:=\s*"\w+"\s*)?\@(\d+)\s*$/;
   # This allows skipping ordinals which were used in older versions
   $sym_ord = $1 if /^\s*;\s*LAST_ORDINAL\s*=\s*(\d+)\s*$/;
      }
      $sym_ord < $_ and $sym_ord = $_ for values %ordinal; # Take the max
    }
}

my %skip;
# All platforms export boot_DynaLoader unconditionally.
my %export = ( boot_DynaLoader => 1 );

sub try_symbols {
    foreach my $symbol (@_) {
   ++$export{$symbol} unless exists $skip{$symbol};
    }
}

sub readvar {
    # $hash is the hash that we're adding to. For one of our callers, it will
    # actually be the skip hash but that doesn't affect the intent of what
    # we're doing, as in that case we skip adding something to the skip hash
    # for the second time.

    my $file = $ARGS{TARG_DIR} . shift;
    my $hash = shift;
    my $proc = shift;
    open my $vars, '<', $file or die die "Cannot open $file: $!
";

    while (<$vars>) {
   # All symbols have a Perl_ prefix because that's what embed.h sticks
   # in front of them.  The A?I?S?C? is strictly speaking wrong.
   next unless / PERLVAR(A?I?S?C?)\(([IGT]),\s*(\w+)/;

   my $var = "PL_$3";
   my $symbol = $proc ? &$proc($1,$2,$3) : $var;
   ++$hash->{$symbol} unless exists $skip{$var};
    }
}

if ($ARGS{PLATFORM} ne 'os2') {
    ++$skip{$_} foreach qw(
           PL_cryptseen
           PL_opsave
           Perl_GetVars
           Perl_dump_fds
           Perl_my_bcopy
           Perl_my_bzero
           Perl_my_chsize
           Perl_my_htonl
           Perl_my_memcmp
           Perl_my_memset
           Perl_my_ntohl
           Perl_my_swap
          );
    if ($ARGS{PLATFORM} eq 'vms') {
   ++$skip{PL_statusvalue_posix};
        # This is a wrapper if we have symlink, not a replacement
        # if we don't.
        ++$skip{Perl_my_symlink} unless $Config{d_symlink};
    } else {
   ++$skip{PL_statusvalue_vms};
   ++$skip{PL_perllib_sep};
   if ($ARGS{PLATFORM} ne 'aix') {
       ++$skip{$_} foreach qw(
            PL_DBcv
            PL_generation
            PL_lastgotoprobe
            PL_modcount
            main
             );
   }
    }
}

#ifndef PHP_LIBXML_H
#define PHP_LIBXML_H

#if HAVE_LIBXML
extern zend_module_entry libxml_module_entry;
#define libxml_module_ptr &libxml_module_entry

#include "php_version.h"
#define PHP_LIBXML_VERSION PHP_VERSION

#ifdef PHP_WIN32
#   define PHP_LIBXML_API __declspec(dllexport)
#elif defined(__GNUC__) && __GNUC__ >= 4
#   define PHP_LIBXML_API __attribute__ ((visibility("default")))
#else
#   define PHP_LIBXML_API
#endif

#include "zend_smart_str.h"
#include <libxml/tree.h>

#define LIBXML_SAVE_NOEMPTYTAG 1<<2

ZEND_BEGIN_MODULE_GLOBALS(libxml)
   zval stream_context;
   smart_str error_buffer;
   zend_llist *error_list;
   struct _php_libxml_entity_resolver {
      zval                    object;
      zend_fcall_info         fci;
      zend_fcall_info_cache   fcc;
   } entity_loader;
   zend_bool entity_loader_disabled;
ZEND_END_MODULE_GLOBALS(libxml)

typedef struct _libxml_doc_props {
   int formatoutput;
   int validateonparse;
   int resolveexternals;
   int preservewhitespace;
   int substituteentities;
   int stricterror;
   int recover;
   HashTable *classmap;
} libxml_doc_props;

typedef struct _php_libxml_ref_obj {
   void *ptr;
   int   refcount;
   libxml_doc_props *doc_props;
} php_libxml_ref_obj;

typedef struct _php_libxml_node_ptr {
   xmlNodePtr node;
   int   refcount;
   void *_private;
} php_libxml_node_ptr;

typedef struct _php_libxml_node_object {
   php_libxml_node_ptr *node;
   php_libxml_ref_obj *document;
   HashTable *properties;
   zend_object  std;
} php_libxml_node_object;


static inline php_libxml_node_object *php_libxml_node_fetch_object(zend_object *obj) {
   return (php_libxml_node_object *)((char*)(obj) - obj->handlers->offset);
}

#define Z_LIBXML_NODE_P(zv) php_libxml_node_fetch_object(Z_OBJ_P((zv)))

typedef void * (*php_libxml_export_node) (zval *object);

PHP_LIBXML_API int php_libxml_increment_node_ptr(php_libxml_node_object *object, xmlNodePtr node, void *private_data);
